496:                     n930x_switch_flash();
497:                     break;
498: 
499:                 case AOP_VOL:
500:                     n930x_volume((uint8_t)r.arg);
501:                     break;
502: 
503:                 case AOP_PLAY:
504:                     n930x_play(r.arg);
505:                     s_last_track    = r.arg;
506:                     s_seg_active    = 1U;
507:                     s_seg_busy_seen = 0U;
508:                     s_seg_tick      = now;
509:                     break;
510: 
511:                 case AOP_STOP:
