$bytes = [System.IO.File]::ReadAllBytes($hmiPath)

# Extract printable ASCII and GBK strings longer than 3 chars
$sb = New-Object System.Text.StringBuilder
$cur = New-Object System.Collections.Generic.List[byte]

for ($i = 0; $i -lt $bytes.Length; $i++) {
    $b = $bytes[$i]
    if ($b -ge 0x20 -and $b -le 0x7E -or $b -eq 0x0A -or $b -eq 0x0D -or $b -ge 0x80) {
        $cur.Add($b)
    } else {
        if ($cur.Count -ge 4) {
            $str = [System.Text.Encoding]::GetEncoding("GBK").GetString($cur.ToArray())
            if ($str -match "tm0|tm_sec|breath_phase|j0|p1|p2|b1|printh") {
                [void]$sb.AppendLine($str)
            }
        }
        $cur.Clear()
    }
}

Set-Content -Path "C:\Users\Administrator\Desktop\淘晶驰git\hmi_strings.txt" -Value $sb.ToString() -Encoding utf8
Write-Output "Done. Length: $($sb.Length)"

$hmiPath = "C:\Users\Administrator\Desktop\淘晶驰git\USART屏幕\projects\NAFLD_backup.HMI"
$bytes = [System.IO.File]::ReadAllBytes($hmiPath)
$text = [System.Text.Encoding]::GetEncoding("GBK").GetString($bytes)

# Find all blocks containing tm0
$matches = [regex]::Matches($text, "(?s)tm0.{0,300}")
foreach ($m in $matches) {
    # filter out binary garbage by checking if printable
    $clean = $m.Value -replace "[^\x20-\x7E\r\n\u4E00-\u9FA5]", " "
    if ($clean -match "j0|val|en|tim") {
        Write-Output "--- MATCH ---"
        Write-Output $clean
    }
}

