151: static void n930x_send(uint8_t cmd, const uint8_t *data, uint8_t len)
152: {
153:     uint8_t frame[24];
154:     uint8_t i;
155:     uint8_t sum;
156: 
157:     if (len > 20U) return;
158: 
159:     frame[0] = cmd;
160:     frame[1] = (uint8_t)(~cmd);            /* 命令码反码 */
161:     frame[2] = len;                        /* 数据个数 */
162:     sum      = (uint8_t)(frame[0] + frame[1] + frame[2]);
163: 
164:     for (i = 0U; i < len; i++)
165:     {
166:         frame[3U + i] = data[i];
167:         sum = (uint8_t)(sum + data[i]);
168:     }
169:     frame[3U + len] = sum;                 /* 校验和 */
170: 
171:     uart2_tx_raw(frame, (uint16_t)(len + 4U));
172: }
