123: /**
124:  * @brief  从环形缓冲区非阻塞提取一帧完整串口屏报文（以连续 0xFF 0xFF 0xFF 结尾）
125:  * @param  frame: 输出参数，存放剥离帧尾后的完整帧内容及关键字段
126:  * @retval 1: 成功读出完整一帧；0: 缓冲区暂无完整帧
127:  */
128: uint8_t BSP_Screen_ReadFrame(ScreenFrame_t *frame)
129: {
130:     if (frame == NULL) return 0U;
131: 
132:     while (s_rx_tail != s_rx_head)
133:     {
134:         uint8_t b = s_rx_ring[s_rx_tail];
135:         s_rx_tail = (uint16_t)((s_rx_tail + 1U) % SCREEN_RX_RING_SIZE);
136: 
137:         /* 先存入临时组帧缓存，若超出最大帧长则丢弃残帧重新同步 */
138:         if (s_frame_len < SCREEN_FRAME_MAX_DATA)
139:         {
140:             s_frame_buf[s_frame_len++] = b;
141:         }
142:         else
143:         {
144:             s_frame_len = 0U;
145:             s_ff_cnt = 0U;
146:             continue;
147:         }
148: 
149:         /* 1. 统一协议定界：检测淘晶驰标准连续 3 个 0xFF 帧结束符 */
150:         if (b == 0xFFU)
151:         {
152:             s_ff_cnt++;
153:             if (s_ff_cnt >= 3U)
154:             {
155:                 if (s_frame_len > 3U)
156:                 {
157:                     /* 剥离末尾 3 字节 0xFF，输出完整有效载荷 */
158:                     uint8_t payload_len = (uint8_t)(s_frame_len - 3U);
159:                     memset(frame, 0, sizeof(*frame));
160:                     memcpy(frame->raw, s_frame_buf, payload_len);
161:                     frame->len     = payload_len;
162:                     frame->header  = frame->raw[0];
163:                     if (frame->header == 0xA5U) frame->header = 0x05U; /* 自动规格化为统一的 0x05 帧头 */
164:                     frame->page    = (payload_len > 1U) ? frame->raw[1] : 0U;
165:                     frame->control = (payload_len > 2U) ? frame->raw[2] : 0U;
166:                     frame->value   = (payload_len > 3U) ? frame->raw[3] : 0U;
167: 
168:                     s_frame_len = 0U;
169:                     s_ff_cnt = 0U;
170:                     return 1U;
171:                 }
172:                 /* 忽略串口屏上电空帧（如 0x00 FF FF FF 或单独的 FF FF FF） */
173:                 s_frame_len = 0U;
174:                 s_ff_cnt = 0U;
175:             }
176:         }
177:         else
178:         {
179:             s_ff_cnt = 0U;
180: 
181:             /* 2. 兼容兜底：若收到旧脚本尾部带 0x5A 的定长帧，也提取并归一化为 0x05 */
182:             if ((s_frame_buf[0] == 0x05U || s_frame_buf[0] == 0xA5U) && b == 0x5AU && s_frame_len >= 4U)
183:             {
184:                 uint8_t payload_len = (uint8_t)s_frame_len;
185:                 memset(frame, 0, sizeof(*frame));
186:                 memcpy(frame->raw, s_frame_buf, payload_len);
187:                 frame->len     = payload_len;
188:                 frame->header  = 0x05U; /* 统一按 0x05 协议分发 */
189:                 frame->page    = (payload_len > 1U) ? frame->raw[1] : 0U;
190:                 frame->control = (payload_len > 2U) ? frame->raw[2] : 0U;
191:                 frame->value   = (payload_len > 3U) ? frame->raw[3] : 0U;
192: 
193:                 s_frame_len = 0U;
194:                 s_ff_cnt = 0U;
195:                 return 1U;
196:             }
197:         }
198:     }
199: 
200:     return 0U;
201: }
