212: /**
213:  * @brief  发送原始串口屏指令并自动附加结束符 0xFF 0xFF 0xFF
214:  * @note   支持使用分号 ';' 分隔的多条复合指令，在单次互斥锁保护下逐条补齐 0xFF 0xFF 0xFF 原子发出，
215:  *         彻底避免淘晶驰协议不识别分号导致报语法错误（0x1A）并吞噬箭头显隐指令的问题
216:  * @param  cmd: ASCII 指令字符串，如 "page running" 或 "vis p1,1;vis p2,0"
217:  * @retval 无
218:  */
219: void BSP_Screen_SendRawCmd(const char *cmd)
220: {
221:     if (cmd == NULL) return;
222: 
223:     uint8_t locked = 0U;
224:     if (s_tx_mutex != NULL)
225:     {
226:         if (osMutexWait(s_tx_mutex, 50U) == osOK)
227:         {
228:             locked = 1U;
229:         }
230:     }
231: 
232:     static const uint8_t end[3] = {0xFFU, 0xFFU, 0xFFU};
233:     const char *p = cmd;
234:     const char *start = cmd;
235: 
236:     while (*p != '\0')
237:     {
238:         if (*p == ';')
239:         {
240:             if (p > start)
241:             {
242:                 HAL_UART_Transmit(&huart3, (uint8_t *)start, (uint16_t)(p - start), 50U);
243:                 HAL_UART_Transmit(&huart3, (uint8_t *)end, 3U, 50U);
244:             }
245:             start = p + 1;
246:         }
247:         p++;
248:     }
249: 
250:     if (p > start)
251:     {
252:         HAL_UART_Transmit(&huart3, (uint8_t *)start, (uint16_t)(p - start), 50U);
253:         HAL_UART_Transmit(&huart3, (uint8_t *)end, 3U, 50U);
254:     }
255: 
256:     if (locked)
257:     {
258:         osMutexRelease(s_tx_mutex);
259:     }
260: }
