130: static void uart2_tx_raw(const uint8_t *buf, uint16_t len)
131: {
132:     USART_TypeDef *u = huart2.Instance;
133:     uint16_t i;
134:     uint32_t guard;
135: 
136:     for (i = 0U; i < len; i++)
137:     {
138:         guard = 0U;
139:         while ((u->SR & USART_SR_TXE) == 0U)
140:         {
141:             if (++guard > 500000U) return;
142:         }
143:         u->DR = buf[i];
144:     }
145: 
146:     guard = 0U;
147:     while ((u->SR & USART_SR_TC) == 0U)
148:     {
149:         if (++guard > 500000U) return;
150:     }
151: }
