153: static void n930x_send(uint8_t cmd, const uint8_t *data, uint8_t len)
154: {
155:     uint8_t frame[24];
156:     uint8_t i;
157:     uint8_t sum;
158: 
159:     if (len > 20U) return;
160: 
161:     frame[0] = cmd;
162:     frame[1] = (uint8_t)(~cmd);            /* 命令码反码 */
163:     frame[2] = len;                        /* 数据个数 */
164:     sum      = (uint8_t)(frame[0] + frame[1] + frame[2]);
165: 
166:     for (i = 0U; i < len; i++)
167:     {
168:         frame[3U + i] = data[i];
169:         sum = (uint8_t)(sum + data[i]);
170:     }
171:     frame[3U + len] = sum;                 /* 校验和 */
172: 
173:     uart2_tx_raw(frame, (uint16_t)(len + 4U));
174: }
