339: /* ======================= 接收解析 ======================= */
340: static void audio_rx_parse(uint8_t b)
341: {
342:     uint8_t need;
343:     uint8_t len;
344:     uint8_t i;
345:     uint8_t sum = 0U;
346: 
347:     if (s_rx_len == 0U)
348:     {
349:         s_rx_frame[s_rx_len++] = b;
350:         return;
351:     }
352: 
353:     if (s_rx_len < AUDIO_FRAME_MAX_LEN)
354:     {
355:         s_rx_frame[s_rx_len++] = b;
356:     }
357:     else
358:     {
359:         s_rx_len = 0U;
360:         return;
361:     }
362: 
363:     if (s_rx_len < 3U) return;
364: 
365:     len = s_rx_frame[2];
366:     if (len > 20U)
367:     {
368:         s_rx_len = 0U;
369:         return;
370:     }
371:     need = (uint8_t)(3U + len + 1U);
372:     if (s_rx_len < need) return;
373: 
374:     /* 命令码 + 反码 校验 */
375:     if ((uint8_t)(s_rx_frame[0] ^ 0xFFU) != s_rx_frame[1])
376:     {
377:         s_rx_len = 0U;
378:         return;
379:     }
380:     /* 校验和 */
381:     for (i = 0U; i < need - 1U; i++) sum = (uint8_t)(sum + s_rx_frame[i]);
382:     if (sum != s_rx_frame[need - 1U])
383:     {
384:         s_rx_len = 0U;
385:         return;
386:     }
387: 
388:     s_last_ack_cmd = s_rx_frame[0];
389:     s_online = 1U;
390: 
391:     if (s_rx_frame[0] == 0xAAU && len >= 2U && s_rx_frame[3] == 0xFFU)
392:     {
393:         s_last_error = s_rx_frame[4];
394:     }
395:     else if (s_rx_frame[0] == 0x04U && len >= 1U)
396:     {
397:         s_last_error = 0U;
398:     }
399: 
400:     s_rx_len = 0U;
401: }
