626: void BSP_Audio_PlayTrack(uint16_t track_id)
627: {
628:     uint32_t now = HAL_GetTick();
629: 
630:     /* 关键修复（问题2）：800ms 内对同一曲目的重复调用直接过滤防抖，杜绝双“吸”音 */
631:     if ((track_id == s_last_play_req_track) && ((now - s_last_play_req_tick) < 800U))
632:     {
633:         return;
634:     }
635: 
636:     /* 1) 新的播放请求要作废“待发的停止”和已排队的停止 */
637:     s_halt_pending = 0U;
638:     audio_req_purge(AOP_STOP);
639: 
640:     /* 2) 同一首正在播、且硬件 BUSY 引脚确实拉低处于播放状态 -> 当作重复触发，直接忽略，避免掐断或重头再来 */
641:     if ((s_seg_active != 0U || audio_req_has(AOP_PLAY) != 0U) && (s_last_track == track_id))
642:     {
643:         if (HAL_GPIO_ReadPin(AUDIO_BUSY_GPIO_Port, AUDIO_BUSY_Pin) == GPIO_PIN_RESET || audio_req_has(AOP_PLAY) != 0U)
644:         {
645:             return;
646:         }
647:     }
648: 
649:     /* 若之前有不同曲目正在播放，立即停止旧曲目，杜绝旧曲目 BUSY 信号干扰新曲目 */
650:     if (s_seg_active != 0U && s_last_track != track_id)
651:     {
652:         n930x_stop();
653:     }
654: 
655:     s_last_play_req_track = track_id;
656:     s_last_play_req_tick  = now;
657: 
658:     /* 3) 单曲：清掉尚未发出的旧曲目，清空多段队列 */
659:     audio_req_purge(AOP_PLAY);
660:     s_q_count       = 0U;
661:     s_q_idx         = 0U;
662:     s_seg_active    = 0U;
663:     s_seg_busy_seen = 0U;
664: 
665:     audio_req_push(AOP_PLAY, track_id);
666:     /* 允许立即发送新曲目播放指令，不等待旧指令间隔 */
667:     if ((now - s_last_tx_tick) < AUDIO_CMD_GAP_MS)
668:     {
669:         s_last_tx_tick = now - AUDIO_CMD_GAP_MS + 20U;
670:     }
671: }
