625: /**
626:  * @brief  串口屏 FreeRTOS 任务入口函数（周期 20 ms）
627:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
628:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
629:  *         3. 每 10 秒刷新一次电池电量图标
630:  * @param  argument: FreeRTOS 任务参数（未使用）
631:  * @retval 无
632:  */
633: void ScreenTask(void const *argument)
634: {
635:     ScreenFrame_t frame;
636:     uint32_t tick_cnt = 0U;
637:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
638:     uint16_t last_remain_s = 0xFFFFU;
639:     (void)argument;
640: 
641:     osDelay(50U);
642: 
643:     /* 启动初期显式关闭屏幕休眠与自动休眠定时器，确保屏幕始终常亮不熄屏 */
644:     BSP_Screen_SendRawCmd("sleep=0");
645:     BSP_Screen_SendRawCmd("usleep=0");
646: 
647:     for (;;)
648:     {
649:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
650:         while (BSP_Screen_ReadFrame(&frame))
651:         {
652:             if (frame.header == SCREEN_FRAME_HDR_CTRL || frame.header == SCREEN_FRAME_HDR_CUSTOM)
653:             {
654:                 if (frame.len >= 3U)
655:                 {
656:                     Screen_HandleCtrlFrame(&frame);
657:                 }
658:             }
659:             else if (frame.header == SCREEN_FRAME_HDR_NUM && frame.len >= 5U)
660:             {
661:                 /* 串口屏返回的数值帧：raw[1..4] 为 32 位小端整数。用于同步 start.set_vol.val 与 start.bt_en.val */
662:                 uint32_t num_val = (uint32_t)frame.raw[1] |
663:                                    ((uint32_t)frame.raw[2] << 8) |
664:                                    ((uint32_t)frame.raw[3] << 16) |
665:                                    ((uint32_t)frame.raw[4] << 24);
666: 
667:                 ScreenQueryState_t query = BSP_Screen_GetPendingQuery();
668:                 if (query == SCREEN_QUERY_SET_VOL)
669:                 {
670:                     uint8_t vol = (num_val > 10U) ? 10U : (uint8_t)num_val;
671:                     App_Therapy_SetVolume(vol);
672:                     BSP_Screen_ClearPendingQuery();
673:                 }
674:                 else if (query == SCREEN_QUERY_BT_EN)
675:                 {
676:                     uint8_t ble_en = (num_val != 0U) ? 1U : 0U;
677:                     App_Therapy_SetBleEnable(ble_en);
678:                     BSP_Screen_ClearPendingQuery();
679:                 }
680:                 else
681:                 {
682:                     if (num_val <= 1U)
683:                     {
684:                         App_Therapy_SetBleEnable((uint8_t)num_val);
685:                     }
686:                     else if (num_val <= 10U)
687:                     {
688:                         App_Therapy_SetVolume((uint8_t)num_val);
689:                     }
690:                 }
691:             }
692:             else if (frame.header == SCREEN_FRAME_HDR_TOUCH) /* 淘晶驰原生触摸帧兜底：0x65 [page] [comp] [event] */
693:             {
694:                 if (frame.len >= 4U)
695:                 {
696:                     Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
697:                 }
698:             }
699:         }
700: 
701:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
702:         if (g_app.running && !g_app.paused)
703:         {
704:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
705:             {
706:                 last_lung = g_app.lung_pct;
707:                 BSP_Screen_SetLungFill(last_lung);
708:             }
709: 
710:             if ((tick_cnt % 5U) == 0U && g_app.Breath_Mode != BREATH_MODE_OFF)
711:             {
712:                 /* 每 100ms 周期性抑制屏幕内部定时器 tm0 与 tm_sec，彻底杜绝屏幕自带逻辑复苏引发动画跑飞 */
713:                 BSP_Screen_SendRawCmd("tm0.en=0;tm_sec.en=0");
714:             }
715: 
716:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
717:             {
718:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
719:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
720:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
721:                 if (rem_s != last_remain_s)
722:                 {
723:                     last_remain_s = rem_s;
724:                     BSP_Screen_SetRemainTimeSec(rem_s);
725:                 }
726:             }
727:         }
728:         else
729:         {
730:             last_lung = 255U;
731:             last_remain_s = 0xFFFFU;
732: 
733:             /* 关键修复（问题2）：处于参数设置页面期间，每 200ms 主动查询一次 start.bt_en.val，
734:              * 使得在设置页面点击蓝牙开关后，即便尚未返回或尚未开启治疗，硬件逻辑也能即刻实时刷新同步！ */
735:             uint8_t cur_page = BSP_Screen_GetCurrentPage();
736:             if ((tick_cnt % 10U) == 0U &&
737:                 (cur_page == SCREEN_PAGE_JIANYISET ||
738:                  cur_page == SCREEN_PAGE_FANKUISET ||
739:                  cur_page == SCREEN_PAGE_ELECSET ||
740:                  cur_page == SCREEN_PAGE_LIANHESET1 ||
741:                  cur_page == SCREEN_PAGE_LIANHESET2))
742:             {
743:                 if (BSP_Screen_GetPendingQuery() == SCREEN_QUERY_NONE)
744:                 {
745:                     BSP_Screen_QueryBleEnable();
746:                 }
747:             }
748:         }
749: 
750:         /* 3. 电池图标暂定不进行变化控制，下位机不参与赋值 */
751:         /*
752:         if ((tick_cnt % 500U) == 0U)
753:         {
754:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
755:         }
756:         */
757: 
758:         tick_cnt++;
759:         osDelay(20U);
760:     }
761: }

