318: void App_Therapy_Resume(void)
319: {
320:     if (g_app.sys_state == APP_STATE_PAUSED || g_app.paused)
321:     {
322:         g_app.paused = 0U;
323: 
324:         /* 恢复运行后按钮切换为暂停图标 (pic = 10) */
325:         BSP_Screen_SetControlBtnPic(1U);
326: 
327:         /* 若是在生物反馈引导未完成时被暂停的，恢复为引导阶段继续检测 */
328:         if (!Algo_Breath_IsBioCalibReady() &&
329:             (s_paused_therapy_page == SCREEN_PAGE_FANKUI || s_paused_therapy_page == SCREEN_PAGE_FANKUIELEC))
330:         {
331:             g_app.sys_state = APP_STATE_BIO_CALIB;
332:             s_bio_calib_tick = HAL_GetTick();
333:             Algo_Breath_StartGuide(10U);
334:             BSP_Audio_PlayVoice(AUDIO_VOICE_BIO_CALIB);
335:             return;
336:         }
337: 
338:         g_app.running = 1U;
339:         g_app.sys_state = APP_STATE_RUNNING;
340: 
341:         if (g_app.Breath_Mode != BREATH_MODE_OFF)
342:         {
343:             /* 继续时重新从吸气阶段 0% 开始引导 */
344:             Algo_Breath_StartGuide(g_app.guide_bpm);
345:             g_app.breath_phase = BREATH_PHASE_INHALE;
346:             g_app.lung_pct     = 0U;
347:             BSP_Screen_SetLungFill(0U);
348:             BSP_Screen_SetBreathArrow(1U); /* 吸气箭头（向左指示） */
349:             apply_combined_phase_to_stim(BREATH_PHASE_INHALE);
350:         }
351: 
352:         if (g_app.Stim_Mode != STIM_MODE_OFF)
353:         {
354:             sync_stimulator_params();
355:             g_app.elec_drop_mask = 0U;
356:             BSP_Stim_SetComboOverride((g_app.Breath_Mode != BREATH_MODE_OFF) ? 1U : 0U,
357:                                       1U, g_app.stim_freq_hz ? g_app.stim_freq_hz : 1U);
358:             BSP_Stim_Enable(1U);
359:         }
360: 
361:         /* 关键修复：纯电刺激模式、联合模式及呼吸模式暂停恢复时，统一播报“开始治疗”语音 */
362:         BSP_Audio_PlayVoice(AUDIO_VOICE_START_TREAT);
363: 
364:         /* 立即同步刷新当前保留的剩余倒计时和频率 */
365:         uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
366:         uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
367:         uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
368:         BSP_Screen_SetRemainTimeSec(rem_s);
369:         BSP_Screen_SetGuideBPM(g_app.guide_bpm);
370:     }
371: }
