627:     s_paused_therapy_page   = 0xFFU;
628:     g_app.Breath_Mode = BREATH_MODE_OFF;
629:     g_app.Stim_Mode   = STIM_MODE_OFF;
630:     g_app.sys_state   = APP_STATE_MENU;
631: 
632:     Algo_Breath_StopGuide();
633:     /* 注意：切勿在此处清除 s_bio_freq_valid！
634:      * 进入设置界面会调用 StopToMenu 停止治疗计时，但必须保留已采集好的生物反馈呼吸频率！
635:      * 只有真正退出到主菜单或重新选择模式时，才由外部显式调用 App_Therapy_ResetBioCalibrationSession() */
636:     BSP_Stim_SetComboOverride(0U, 0U, 1U);
637:     BSP_Stim_Enable(0U);
638:     /* 关键修复（问题7）：退出到菜单无条件终止所有正在播放或排队的音频，杜绝提示音泄漏到菜单 */
639:     BSP_Audio_Stop();
640:     BSP_Screen_SetLungFill(0U);
641:     BSP_Screen_SetBreathArrow(0U);
642: 
643:     /* 恢复按键解锁（若之前在采集中退回） */
644:     BSP_Screen_SendRawCmd("tsw b1,1");
645:     BSP_Screen_SendRawCmd("tsw b0,1");
646: }
