611: 
612:     /* 关键修复（问题1 & 3）：若音量未变且已经就绪下发过，直接返回 */
613:     if (hw_vol == s_current_hw_vol && s_ready != 0U && s_pending_deferred_hw_vol == 0xFFU)
614:     {
615:         return;
616:     }
617:     s_current_hw_vol = hw_vol;
618: 
619:     /* 若芯片尚未就绪（上电 1s 静默期），等待 s_ready 到期后自动下发 */
620:     if (!s_ready)
621:     {
622:         return;
623:     }
624: 
625:     /* 关键修复（问题1）：若芯片正在播放提示音（如0007生物反馈长语音或呼吸引导语音），
626:      * 绝不下发串口音量指令，避免 N9300 收到串口指令后重置/截断当前音频！
627:      * 保存至 s_pending_deferred_hw_vol，在段落播放完毕空闲时自动补发 */
628:     if (s_seg_active != 0U || audio_req_has(AOP_PLAY) != 0U || BSP_Audio_IsBusy())
629:     {
630:         s_pending_deferred_hw_vol = hw_vol;
631:         return;
632:     }
633: 
634:     s_pending_deferred_hw_vol = 0xFFU;
635:     audio_req_replace_or_push(AOP_VOL, hw_vol);   /* 音量只保留最新一条，不占队、不滞后 */
636: }
