                s_current_level_f[ch] = 0.0f; /* 恢复时触发软启动平滑爬升 */
            }
        }
        else
        {
            /* 探测脉冲未能检测到持续接触，重置恢复确认计时 */
            s_elec_recover_start_ms[ch] = 0U;
        }
    }
}

